ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS identity_back_doc_path text;
CREATE OR REPLACE FUNCTION public.bm_review_identity(_profile_id uuid,_approve boolean,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO p FROM public.profiles WHERE id=_profile_id FOR UPDATE; IF NOT FOUND OR p.verification_status<>'PENDENTE_ANALISE' THEN RAISE EXCEPTION 'Request no longer pending'; END IF; IF _approve AND (p.identity_doc_path IS NULL OR p.identity_back_doc_path IS NULL OR p.selfie_path IS NULL) THEN RAISE EXCEPTION 'All three documents required'; END IF; IF NOT _approve AND length(trim(coalesce(_reason,'')))=0 THEN RAISE EXCEPTION 'Rejection reason required'; END IF; UPDATE public.profiles SET verification_status=CASE WHEN _approve THEN 'VERIFICADO' ELSE 'REJEITADO' END,verification_rejection_reason=CASE WHEN _approve THEN NULL ELSE left(trim(_reason),500) END,verification_reviewed_at=now(),verification_reviewed_by=auth.uid() WHERE id=_profile_id; INSERT INTO public.admin_actions(admin_id,action,target_id,reason) VALUES(auth.uid(),CASE WHEN _approve THEN 'approve_identity' ELSE 'reject_identity' END,_profile_id,CASE WHEN _approve THEN NULL ELSE left(trim(_reason),500) END); END $$;